{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Elbasvir, the closest structural analogue sharing the carbamate-proline-imidazole scaffold, has an absolute oral bioavailability of approximately 32% in HCV-infected subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ledipasvir, another HCV NS5A inhibitor with the same bis-proline carbamate scaffold, has an oral bioavailability of about 53%, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Acalabrutinib, despite lower structural similarity, has a geometric mean absolute bioavailability of 25%, providing additional evidence that the F ≥ 20% threshold is achievable for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Atazanavir has an oral bioavailability of about 60% in humans, supporting the general expectation of moderate-to-good oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alpelisib has an oral bioavailability of around 68.7% in healthy subjects, further supporting a high-bioavailability prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%). The query is daclatasvir, a HCV NS5A inhibitor; the closest analogue elbasvir has F ~32%, ledipasvir ~53%, and the broader evidence set overwhelmingly supports moderate-to-good oral bioavailability. No affirmative low-bioavailability evidence transfers to this scaffold.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the supplied evidence; the closest records are for elbasvir and ledipasvir.",
    "Fasted-state-specific data for the query are not directly reported, although the query condition is fasted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

